{
  "scenario_id": "sc-2d248f",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "volatility",
      "direction": "dispersion",
      "magnitude": "empirical YoY sd of A/E ~0.60 vs Poisson ~0.026 (~23x overdispersion); yearly A/E oscillates ~0.41 to ~1.65 while level stays flat (mean 1.006, trend R2=0.01)",
      "confidence": 0.9,
      "evidence": [
        "artifacts/ae_ip_by_year.csv: large alternating swings — 2015 AE=0.413, 2016 AE=1.654, 2018=0.931, 2020 AE=1.612, 2021=0.935, 2022 AE=0.740, 2023 AE=0.794, 2024 AE=0.965",
        "summary.json: IP overall A/E 0.9995 and overall_termination_ae 1.0001 (level and termination rates are at baseline, so the anomaly is dispersion, not a level shift)",
        "evidence pack: IP YoY sd 0.5956 vs Poisson 0.0263 (overdispersion x22.66, Poisson null invalid); max 1yr move 1.241 exceeds net excursion (2.68x) — line oscillates rather than holding a new level; trend gradient -0.012/yr with R2=0.01 (no sustained drift)"
      ],
      "recommended_action": "Do not flag individual IP years against a 1/sqrt(E) Poisson null (invalid at x22.66 overdispersion). Investigate the source of the erratic claim A/E: pull segment/diagnosis-level IP claims detail for the swing years (2015 shortfall, 2016 and 2020 spikes, 2022-23 trough) to test for bulk/late-reported claim lumps, policy-form or eligibility changes, or misattribution of exposures/durations in the expected-claims build; review expected IP claims methodology (in-force data, duration attribution) before touching pricing/valuation assumptions; monitor 2024 (0.965) to confirm the line has re-anchored near 1.0."
    }
  ]
}

